package main

import (
	"errors"
	"net/http"
	"net/http/httptest"
	"testing"
	"time"
)

func TestProbeConflict(t *testing.T) {
	store := NewStore(time.Minute)
	store.now = func() time.Time { return time.Unix(1000, 0) }
	if _, err := store.Create("s1", "alice"); err != nil {
		t.Fatalf("first create errored: %v", err)
	}
	s, err := store.Create("s1", "bob")
	if err == nil {
		t.Fatal("duplicate create must return an error")
	}
	if !errors.Is(err, ErrConflict) {
		t.Fatalf("error = %v, want ErrConflict", err)
	}
	if s.User != "alice" {
		t.Fatalf("existing session must be returned unchanged, got user %q", s.User)
	}
	// Expired id is replaceable.
	store.now = func() time.Time { return time.Unix(2000, 0) }
	if _, err := store.Create("s1", "carol"); err != nil {
		t.Fatalf("create after expiry errored: %v", err)
	}
	// Handler returns 409 on conflict.
	handler := sessionHandler(store)
	store.now = func() time.Time { return time.Unix(2001, 0) }
	rec := httptest.NewRecorder()
	handler(rec, httptest.NewRequest("POST", "/session?id=s1&user=dave", nil))
	if rec.Code != http.StatusConflict {
		t.Fatalf("conflict status = %d, want 409", rec.Code)
	}
}
EOF
