package main

import (
	"encoding/json"
	"log"
	"net/http"
	"time"
)

func main() {
	store := NewStore(30 * time.Minute)
	http.HandleFunc("/session", sessionHandler(store))
	http.HandleFunc("/healthz", healthHandler(store))
	log.Println("listening on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}

// sessionHandler creates a session on POST and reads one on GET.
func sessionHandler(store *Store) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		switch r.Method {
		case http.MethodPost:
			id := r.URL.Query().Get("id")
			user := r.URL.Query().Get("user")
			if id == "" || user == "" {
				http.Error(w, "id and user are required", http.StatusBadRequest)
				return
			}
			session, err := store.Create(id, user)
			if err != nil {
				http.Error(w, err.Error(), http.StatusConflict)
				return
			}
			writeJSON(w, session)
		case http.MethodGet:
			session, err := store.Get(r.URL.Query().Get("id"))
			if err != nil {
				http.Error(w, err.Error(), http.StatusNotFound)
				return
			}
			writeJSON(w, session)
		default:
			http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
		}
	}
}

// healthHandler reports how many sessions are currently held.
func healthHandler(store *Store) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		writeJSON(w, map[string]int{"sessions": store.Len()})
	}
}

func writeJSON(w http.ResponseWriter, payload any) {
	w.Header().Set("Content-Type", "application/json")
	if err := json.NewEncoder(w).Encode(payload); err != nil {
		log.Printf("write response: %v", err)
	}
}

gold.session_test.go:
package main

import (
	"errors"
	"testing"
	"time"
)

func TestStoreCreateAndGet(t *testing.T) {
	store := NewStore(time.Minute)
	created, err := store.Create("abc", "ada")
	if err != nil {
		t.Fatalf("first create: %v", err)
	}
	if created.User != "ada" {
		t.Fatalf("created user = %q, want ada", created.User)
	}
	found, err := store.Get("abc")
	if err != nil {
		t.Fatalf("Get: %v", err)
	}
	if found.ID != "abc" || found.User != "ada" {
		t.Fatalf("found session = %+v, want abc/ada", found)
	}
	if store.Len() != 1 {
		t.Fatalf("store length = %d, want 1", store.Len())
	}
}

func TestStoreExpiresIdleSession(t *testing.T) {
	store := NewStore(time.Minute)
	clock := time.Now()
	store.now = func() time.Time { return clock }
	if _, err := store.Create("abc", "ada"); err != nil {
		t.Fatalf("create: %v", err)
	}

	clock = clock.Add(2 * time.Minute)
	if _, err := store.Get("abc"); !errors.Is(err, ErrNotFound) {
		t.Fatalf("Get after ttl = %v, want ErrNotFound", err)
	}
	if store.Len() != 0 {
		t.Fatalf("expired session was not dropped: length = %d", store.Len())
	}
}

